using EnterpriseDocumentIntelligence.BuildingBlocks.Security;
public sealed class AgentHarness(IAgentModel model,HybridSearchApplication search,ICurrentUser user){public async Task<AgentResult>RunAsync(string prompt,int maxTools,int maxTokens,CancellationToken ct){var tool=new SearchAgentTool(search,user);var orchestrator=new AgentOrchestrator(model,new Dictionary<string,IAgentTool>(StringComparer.OrdinalIgnoreCase){{tool.Name,tool}});var result=await orchestrator.RunAsync(prompt,maxTools,maxTokens,ct);return new(result.Answer,result.Citations,result.ToolCalls,result.Tokens);}}
public sealed class SearchAgentTool(HybridSearchApplication search,ICurrentUser user):IAgentTool{public string Name=>"document_search";public async Task<string>ExecuteAsync(string arguments,CancellationToken ct=default){using var doc=System.Text.Json.JsonDocument.Parse(arguments);var query=doc.RootElement.GetProperty("query").GetString()??throw new ArgumentException("query required");var top=doc.RootElement.TryGetProperty("topK",out var k)?k.GetInt32():8;var hits=await search.SearchAsync(user.TenantId,user.UserId,new SearchQuery(query,top),ct);return string.Join("\n",hits.Select(x=>$"CITATION: {x.Citation}\n{x.Text}"));}}
public sealed record AgentResult(string Answer,IReadOnlyList<string> Citations,int ToolCalls,int Tokens);